class Interest {
  double principal;
  int years;
  Interest(double p, int y) {
    principal = p;
    years = y;
  }
  double simple() {
    return principal * 5 * years / 100;
  }
  void show() {
    System.out.println("Interest = " + simple());
  }
  public static void main(String[] args) {
    Interest i = new Interest(1800, 3);
    i.show();
  }
}
```

